  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Solving Multi Step Equations$j$, $j${"body": "To solve an equation, undo operations in reverse order to get the variable alone. Whatever you do to one side, do to the other. Steps: distribute, combine like terms, move variable terms to one side, undo addition or subtraction, then undo multiplication or division. Always check by substituting.\n\nWorked example: Solve 3(x − 4) + 5 = 2x + 9.\n3x − 12 + 5 = 2x + 9, so 3x − 7 = 2x + 9, so x = 16.\nCheck: 3(12) + 5 = 41 and 2(16) + 9 = 41. Correct.\n\nWord problem: A plumber charges $40 plus $25 per hour. How many hours for a $165 bill? 40 + 25h = 165, so 25h = 125 and h = 5.\n\nThink it through: an equation is a balanced scale. Whatever you do to one side, you must do to the other, and the goal is to get the variable alone. Work in this order: clear parentheses, combine like terms, gather the variable on one side, and then undo addition and subtraction before multiplication and division. Example: 2(x + 3) = 14. Divide both sides by 2 to get x + 3 = 7, so x = 4. Check: 2(4 + 3) = 14. The check takes ten seconds and catches most mistakes. For word problems, say what the variable stands for before you write the equation.\n\nYour task: solve (a) 2x + 7 = 19 (b) 5x − 3 = 2x + 12 (c) 4(x − 1) = 20 (d) 3(x + 2) = 27, and write and solve one equation of your own from a real situation.\n\nFlorida standards: MA.912.AR.2.1.", "video": "", "script": "An equation is a statement that two expressions are equal, like a balanced scale. Solving an equation means finding the value of the variable that keeps the scale balanced. The one rule is this: whatever you do to one side, you must do to the other.\n\nLet us start with a simple one. Two x plus seven equals nineteen. To get x alone, we undo what was done to it, in reverse order. First, undo the addition by subtracting seven from both sides. That gives two x equals twelve. Then undo the multiplication by dividing both sides by two. x equals six.\n\nNow a multi step equation. Three times the quantity x minus four, plus five, equals two x plus nine. Step one, distribute. Three x minus twelve plus five equals two x plus nine. Step two, combine like terms on each side. Three x minus seven equals two x plus nine. Step three, get the variable terms on one side by subtracting two x from both sides. x minus seven equals nine. Step four, add seven to both sides. x equals sixteen.\n\nAlways check your answer. Put sixteen back in the original equation. Three times twelve is thirty six, plus five is forty one. Two times sixteen is thirty two, plus nine is forty one. Both sides match, so the answer is correct.\n\nEquations become powerful when they model real situations. A plumber charges forty dollars for the visit and twenty five dollars for each hour of work. If the bill is one hundred sixty five dollars, how many hours did the plumber work? Let h be the hours. The equation is forty plus twenty five h equals one hundred sixty five. Subtract forty, and we get twenty five h equals one hundred twenty five. Divide by twenty five, and h equals five hours.\n\nNotice the pattern for word problems. First, define your variable. Second, write the equation from the story. Third, solve. Fourth, answer in a sentence with units, and check that your answer makes sense.\n\nYour task today is to solve four equations and to write one of your own from a real situation. Then take the four question check.\n\nSolving equations is really about patience and order. As the Preacher says, to every thing there is a season, and a time to every purpose. Take each step in its season. Excellence, Faith, Purpose. I will see you in the next lesson.", "readings": [], "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.AR.2.1"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Solving Multi Step Equations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Literal Equations and Formulas$j$, $j${"body": "A literal equation has several letters. To solve for one letter, treat the others as numbers and undo operations to isolate it.\n\nWorked examples:\nd = rt, solve for t: t = d/r.\nP = 2l + 2w, solve for w: 2w = P − 2l, so w = (P − 2l)/2.\ny = mx + b, solve for x: x = (y − b)/m.\nA = ½bh, solve for h: h = 2A/b.\n\nThink it through: solving for a letter in a formula uses the same steps as solving any equation. The other letters simply stay in the answer as if they were numbers. Take A = ½bh and solve for h. Multiply both sides by 2 to get 2A = bh, then divide both sides by b to get h = 2A/b. A common mistake is dividing only part of one side. In P = 2l + 2w, after you subtract 2l you must divide the whole side by 2, so w = (P − 2l)/2. Formulas like these are tools. Builders, nurses and pilots rearrange them every day.\n\nYour task: (a) Solve d = rt for r. (b) Solve P = 2l + 2w for l. (c) Solve y = mx + b for m. (d) Solve A = ½bh for b. (e) Solve C = 2πr for r.\n\nFlorida standards: MA.912.AR.1.2.", "video": "", "script": "A formula is an equation that relates several quantities, like distance equals rate times time. Sometimes you know a different quantity and need to rearrange the formula to find what you want. That is what solving a literal equation means: solving for one letter in terms of the others.\n\nThe process is exactly like solving an ordinary equation. The only difference is that the answer will contain letters. Treat the other letters like numbers, and undo operations in reverse order.\n\nStart with distance equals rate times time. If you want to find the time, divide both sides by the rate. The time equals the distance divided by the rate. If a car travels one hundred twenty miles at sixty miles per hour, the time is two hours.\n\nNow the perimeter of a rectangle: P equals two l plus two w. Suppose we want the width. First subtract two l from both sides. That leaves two w equals P minus two l. Then divide both sides by two. The width equals the quantity P minus two l, all divided by two.\n\nNext, the slope intercept form of a line: y equals m x plus b. To solve for x, subtract b from both sides, then divide by m. x equals the quantity y minus b, divided by m. To solve for m instead, subtract b, then divide by x. Which letter you isolate depends on what you need.\n\nHere is another one: the area of a triangle, A equals one half b h. To solve for h, multiply both sides by two to clear the fraction, getting two A equals b h. Then divide by b. The height equals two A over b.\n\nA few reminders. Keep the order. If a letter is added, subtract it. If it is multiplied, divide by it. If something is in parentheses, you may need to treat the whole group as one piece. And remember that you cannot divide by zero, so we assume the letters we divide by are not zero.\n\nYour task today is to solve five formulas for the letter requested. Then take the four question check.\n\nIn ministry as in math, we often need to work backward from the result we want to the resources we need. Counting the cost is a form of solving for the unknown. Excellence, Faith, Purpose. I will see you in the next lesson.", "readings": [], "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.AR.1.2"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Literal Equations and Formulas$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Linear Inequalities$j$, $j${"body": "An inequality compares with <, >, ≤ or ≥. Solve it like an equation, with one new rule: when you multiply or divide both sides by a negative number, reverse the inequality sign.\n\nWorked examples:\n3x − 5 > 10 gives 3x > 15, so x > 5.\n−2x ≤ 8 gives x ≥ −4 (the sign flips).\nCompound: −3 < 2x + 1 ≤ 9 gives −4 < 2x ≤ 8, so −2 < x ≤ 4.\n\nGraphing: an open circle for < or >, a closed circle for ≤ or ≥.\n\nWord problem: A student has $60 and each book costs $8. 8b ≤ 60, so b ≤ 7.5. She can buy at most 7 books.\n\nThink it through: an inequality has many solutions, so the answer is a range of numbers rather than one value. The sign flips only when you multiply or divide by a negative number. Test your answer with real numbers. For −2x ≤ 8 we found x ≥ −4. Try x = 0: −2(0) = 0, and 0 ≤ 8 is true, and 0 is in the answer. Try x = −5: −2(−5) = 10, and 10 ≤ 8 is false, and −5 is not in the answer. Both tests agree. In a word problem, read the answer in context. Seven and a half books makes no sense, so the answer is 7 books.\n\nYour task: solve and describe the graph of (a) 4x + 3 < 19 (b) −3x ≥ 12 (c) −5 ≤ 2x − 1 < 7, and write one inequality from a real situation.\n\nFlorida standards: MA.912.AR.2.6.", "video": "", "script": "An equation says two things are equal. An inequality says one thing is greater than, or less than, another. The symbols are less than, greater than, less than or equal to, and greater than or equal to. The solution to an inequality is usually not one number, but a whole range of numbers.\n\nWe solve inequalities almost exactly like equations. We add, subtract, multiply and divide to get the variable alone. But there is one special rule. When you multiply or divide both sides by a negative number, you must reverse the direction of the inequality sign.\n\nWhy? Think of the numbers two and five. Two is less than five. Multiply both by negative one, and you get negative two and negative five. Now negative two is greater than negative five. The order flipped. So when we divide by a negative, we flip the sign.\n\nLet us try some. Three x minus five is greater than ten. Add five to both sides, and three x is greater than fifteen. Divide by three, and x is greater than five. No flip, because we divided by a positive.\n\nNow negative two x is less than or equal to eight. Divide both sides by negative two. Because we divided by a negative, we flip the sign, and x is greater than or equal to negative four.\n\nNext, a compound inequality: negative three is less than two x plus one, which is less than or equal to nine. We do the same thing to all three parts. Subtract one from each part. Negative four is less than two x, which is less than or equal to eight. Divide each part by two. Negative two is less than x, which is less than or equal to four.\n\nTo graph, use an open circle for strictly less than or greater than, and a closed circle when equal is included. Then shade the numbers that work.\n\nInequalities describe limits in real life. Suppose a student has sixty dollars and each book costs eight dollars. The number of books b must satisfy eight b is less than or equal to sixty. Dividing gives b is at most seven and a half. Since you cannot buy half a book, the most she can buy is seven.\n\nYour task today is to solve and graph three inequalities, and to write one from a real situation. Then take the four question check.\n\nWise people know their limits. Jesus said to count the cost before building a tower. Inequalities help us do just that. Excellence, Faith, Purpose. I will see you in the next lesson.", "readings": [], "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.AR.2.6"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Linear Inequalities$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Absolute Value Equations and Graphs$j$, $j${"body": "The absolute value |x| is the distance from x to 0, so it is never negative. |5| = 5 and |−5| = 5.\n\nTo solve |expression| = k with k > 0, write two equations: expression = k and expression = −k. If k < 0 there is no solution.\n\nWorked examples:\n|x − 3| = 5 gives x − 3 = 5 or x − 3 = −5, so x = 8 or x = −2.\n|2x + 1| = 9 gives 2x + 1 = 9 or 2x + 1 = −9, so x = 4 or x = −5.\n\nGraph: y = |x| is a V with its vertex at (0, 0). In y = |x − h| + k the vertex is (h, k). So y = |x − 2| + 1 has vertex (2, 1).\n\nThink it through: absolute value measures distance from zero, and distance is never negative. So |x − 3| = 5 asks which numbers are 5 units away from 3. Count 5 to the right to get 8 and 5 to the left to get −2. That is why there are two answers. If the problem says |x| = −4, there is no solution, because distance cannot be negative. Always isolate the absolute value expression first, then split into two equations. Check both answers in the original equation. On a graph, the vertex of y = |x − h| + k is the point where the V turns, at (h, k).\n\nYour task: solve (a) |x| = 7 (b) |x + 4| = 6 (c) |3x − 2| = 10, and state the vertex of y = |x + 1| − 3.\n\nFlorida standards: MA.912.AR.4.1, MA.912.AR.4.3.", "video": "", "script": "The absolute value of a number is its distance from zero on the number line. Distance is never negative, so absolute value is never negative. The absolute value of five is five, and the absolute value of negative five is also five, because both are five steps from zero.\n\nWe write absolute value with two vertical bars. So when we see the absolute value of x equals seven, we are asking, which numbers are seven units away from zero? There are two: seven and negative seven.\n\nThat is the key idea for solving absolute value equations. If the absolute value of an expression equals a positive number k, then the expression equals k, or the expression equals negative k. You write two equations and solve both.\n\nTry this one: the absolute value of x minus three equals five. Either x minus three equals five, so x is eight, or x minus three equals negative five, so x is negative two. The answers are eight and negative two. Both are five units from three on the number line, which makes sense because the equation is really asking, which numbers are five units away from three?\n\nAnother one: the absolute value of two x plus one equals nine. First case: two x plus one equals nine, so two x equals eight and x is four. Second case: two x plus one equals negative nine, so two x equals negative ten and x is negative five. The answers are four and negative five.\n\nWatch out for a special case. If the absolute value of something equals a negative number, there is no solution, because distance cannot be negative.\n\nNow graphing. The graph of y equals the absolute value of x is a V shape with its corner, called the vertex, at the origin. The graph of y equals the absolute value of x minus h, plus k, is the same V moved h units right and k units up. So y equals the absolute value of x minus two, plus one, has its vertex at the point two comma one. The graph is symmetric: the left side mirrors the right side.\n\nYour task today is to solve three absolute value equations and find the vertex of one graph. Then take the four question check.\n\nAbsolute value teaches an important lesson. Whether you are walking toward or away, the distance is what it is. Truth does not change with our direction. Excellence, Faith, Purpose. I will see you in the next lesson.", "readings": [], "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.AR.4.1, MA.912.AR.4.3"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Absolute Value Equations and Graphs$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Equations and Inequalities, Show Your Work$j$, $j${"prompt": "Show every step. (1) Solve 7x − 3 = 4x + 15 and check. (2) Solve 2(3x − 1) = 5x + 7. (3) Solve A = ½h(b₁ + b₂) for h. (4) Solve and graph −4x + 3 > 11. (5) Solve |3x − 6| = 12. (6) Write and solve an equation or inequality for this situation: a church van rental costs $90 plus $0.50 per mile, and the youth ministry can spend at most $200. How many miles can they drive?", "rubric": "Total 100. Items 1 to 5 are worth 15 each (10 for the answer, 5 for work shown). Item 6 is worth 25: correct inequality 0.5m + 90 ≤ 200 (10), solves to m ≤ 220 (10), answers in a sentence with units (5)."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Equations and Inequalities, Show Your Work$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Counting the Cost$j$, $j${"prompt": "Jesus said that a builder first sits down and counts the cost. Describe a real decision where you used or could use an equation or an inequality to set a budget or a limit. What were the variables? Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Counting the Cost$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Solving Multi Step Equations$j$, $j${"questions": [{"q": "Solve 2x + 7 = 19.", "options": ["x = 12", "x = 6", "x = 13", "x = 5"]}, {"q": "Solve 5x − 3 = 2x + 12.", "options": ["x = 5", "x = 15", "x = 3", "x = 9/7"]}, {"q": "Solve 3(x + 2) = 27.", "options": ["x = 9", "x = 25", "x = 7", "x = 3"]}, {"q": "A plumber charges $40 plus $25 per hour. The bill is $165. How many hours did the plumber work?", "options": ["4 hours", "8.2 hours", "5 hours", "6 hours"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Solving Multi Step Equations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,2,2}'::int[], array[$j$2x = 12, so x = 6.$j$,$j$3x = 15, so x = 5.$j$,$j$x + 2 = 9, so x = 7.$j$,$j$40 + 25h = 165, so 25h = 125 and h = 5.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Solving Multi Step Equations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Literal Equations and Formulas$j$, $j${"questions": [{"q": "Solve d = rt for t.", "options": ["t = d/r", "t = r/d", "t = d − r", "t = dr"]}, {"q": "Solve P = 2l + 2w for l.", "options": ["l = (P − 2w)/2", "l = (P + 2w)/2", "l = P − 2w", "l = 2P − w"]}, {"q": "Solve y = mx + b for m.", "options": ["m = (y + b)/x", "m = yx − b", "m = (y − b)/x", "m = y − b − x"]}, {"q": "Solve A = ½bh for b.", "options": ["b = 2Ah", "b = A − h/2", "b = 2A/h", "b = A/(2h)"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Literal Equations and Formulas$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,2}'::int[], array[$j$Divide both sides by r.$j$,$j$Subtract 2w, then divide by 2.$j$,$j$Subtract b, then divide by x.$j$,$j$Multiply by 2, then divide by h.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Literal Equations and Formulas$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Linear Inequalities$j$, $j${"questions": [{"q": "Solve 3x − 5 > 10.", "options": ["x > 5/3", "x > 15", "x < 5", "x > 5"]}, {"q": "Solve −2x ≤ 8.", "options": ["x ≤ −4", "x ≥ −4", "x ≥ 4", "x ≤ 4"]}, {"q": "Solve −3 < 2x + 1 ≤ 9.", "options": ["−4 < x ≤ 8", "−1 < x ≤ 5", "−2 ≤ x < 4", "−2 < x ≤ 4"]}, {"q": "A student has $60 and each book costs $8. What is the most books she can buy?", "options": ["6", "7", "7.5", "8"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Linear Inequalities$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,3,1}'::int[], array[$j$3x > 15, so x > 5.$j$,$j$Dividing by a negative flips the sign: x ≥ −4.$j$,$j$Subtract 1 from each part, then divide each by 2.$j$,$j$8b ≤ 60 gives b ≤ 7.5, and she cannot buy half a book.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Linear Inequalities$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Absolute Value Equations and Graphs$j$, $j${"questions": [{"q": "Solve |x| = 7.", "options": ["x = 7 only", "No solution", "x = 7 or x = −7", "x = −7 only"]}, {"q": "Solve |x − 3| = 5.", "options": ["x = −8 or x = 2", "x = 8 or x = 2", "x = 8 or x = −2", "x = 5"]}, {"q": "Solve |2x + 1| = 9.", "options": ["x = 5 or x = −4", "x = 4 only", "x = 4 or x = −5", "x = 8 or x = −10"]}, {"q": "What is the vertex of y = |x − 2| + 1?", "options": ["(2, −1)", "(−2, 1)", "(1, 2)", "(2, 1)"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Absolute Value Equations and Graphs$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,2,3}'::int[], array[$j$Both 7 and −7 are 7 units from zero.$j$,$j$x − 3 = 5 gives 8, and x − 3 = −5 gives −2.$j$,$j$2x + 1 = 9 gives 4, and 2x + 1 = −9 gives −5.$j$,$j$In y = |x − h| + k the vertex is (h, k).$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Absolute Value Equations and Graphs$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Linear Equations, Inequalities and Absolute Value$j$, $j${"questions": [{"q": "Solve 6x − 4 = 2x + 20.", "options": ["x = 4", "x = 6", "x = 3", "x = 8"]}, {"q": "Solve C = 2πr for r.", "options": ["r = C − 2π", "r = 2πC", "r = 2C/π", "r = C/(2π)"]}, {"q": "Solve −x/2 > 3.", "options": ["x > 6", "x < −6", "x < 6", "x > −6"]}, {"q": "Solve |x + 4| = 6.", "options": ["x = −2 or x = −10", "x = 2 or x = −10", "x = 10 or x = −2", "x = 2 only"]}, {"q": "Solve 5(x − 2) = 3x + 4.", "options": ["x = 14", "x = 7", "x = 1", "x = 3"]}, {"q": "Solve 2x − 1 ≥ 7.", "options": ["x ≥ 3", "x ≥ 8", "x ≤ 4", "x ≥ 4"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Linear Equations, Inequalities and Absolute Value$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,1,1,1,3}'::int[], array[$j$4x = 24, so x = 6.$j$,$j$Divide both sides by 2π.$j$,$j$Multiply by −2 and flip the sign: x < −6.$j$,$j$x + 4 = 6 gives 2, and x + 4 = −6 gives −10.$j$,$j$5x − 10 = 3x + 4, so 2x = 14.$j$,$j$2x ≥ 8, so x ≥ 4.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Linear Equations, Inequalities and Absolute Value$j$ on conflict (item_id) do nothing;
